package com.adc.application;
import com.adc.domain.clinicaltreatment.ClinicalTreatmentRules;
import com.adc.domain.patients.PatientRules;
import com.adc.domain.shared.*;
import com.adc.identity.IdentityGate;
import com.adc.infrastructure.*;
import java.time.*;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import tools.jackson.databind.json.JsonMapper;

@Service @Transactional(isolation=Isolation.READ_COMMITTED,rollbackFor=Exception.class)
public class ClinicalTreatmentService implements ReceiptPolicy {
    private final AtomicCommandExecutor commands;private final IdentityGate gate;private final ClinicalTreatmentStore store;private final AppointmentTransitionStore appointments;private final AppointmentBookingStore booking;private final ScheduleStore schedules;private final PatientStore patients;private final AuditWriter audit;private final Clock clock;private static final JsonMapper JSON=JsonMapper.builder().build();
    public ClinicalTreatmentService(AtomicCommandExecutor commands,IdentityGate gate,ClinicalTreatmentStore store,AppointmentTransitionStore appointments,AppointmentBookingStore booking,ScheduleStore schedules,PatientStore patients,AuditWriter audit,Clock clock){this.commands=commands;this.gate=gate;this.store=store;this.appointments=appointments;this.booking=booking;this.schedules=schedules;this.patients=patients;this.audit=audit;this.clock=clock;}
    public record Record(long treatment,String units,Instant performed) { }
    public record View(Map<String,Object> body,String etag) { }
    private String noteVersion(long appointment){var version=new LinkedHashMap<String,Object>();version.put("appointment",booking.view(appointment));version.put("problems_or_special_needs",store.notes(appointment));return JSON.writeValueAsString(version);}
    private long doctor(IdentityGate.Identity actor,long appointment,String capability){var facts=appointments.facts(appointment);if(actor.dentistId()==null)throw new DomainFailure(403,"DENTIST_IDENTITY_REQUIRED");gate.requireStaff(actor,"DENTIST",capability,facts.clinic());return actor.dentistId();}
    private void priceAuthority(IdentityGate.Identity actor,long id){var row=store.raw(id);gate.requireStaff(actor,"HEADQUARTERS","correctTreatmentPrice",appointments.facts(Long.parseLong((String)row.get("appointment_id"))).clinic());}
    private AtomicCommandExecutor.Result result(long appointment,Long applied,String reason,String verification,Object changes){var refs=new ArrayList<String>();refs.add("Appointment:"+appointment);var summary=new LinkedHashMap<String,Object>();summary.put("appointment_id",Long.toString(appointment));if(applied!=null){refs.add("AppliedTreatment:"+applied);summary.put("applied_treatment_id",Long.toString(applied));}return new AtomicCommandExecutor.Result(JSON.writeValueAsString(refs),JSON.writeValueAsString(summary),200,applied==null?"Appointment":"AppliedTreatment",Long.toString(applied==null?appointment:applied),List.of(appointments.facts(appointment).clinic()),reason,verification,changes==null?null:JSON.writeValueAsString(changes));}
    private Map<String,Object> resolve(AtomicCommandExecutor.Command command,AtomicCommandExecutor.Result result,boolean applied){var actor=gate.authenticate(command.token(),command.client());authorize(actor,command.operation(),result.refs());var summary=JSON.readTree(result.summary());return applied?store.view(Long.parseLong(summary.get("applied_treatment_id").asText())):booking.view(Long.parseLong(summary.get("appointment_id").asText()));}
    public Map<String,Object> record(AtomicCommandExecutor.Command command,long appointment,Record input)throws Exception{
        var result=commands.execute(command,actor->doctor(actor,appointment,"recordAppliedTreatment"),actor->{long dentist=doctor(actor,appointment,"recordAppliedTreatment");store.lock(appointment,dentist);var facts=appointments.facts(appointment);ClinicalTreatmentRules.open(facts.status(),store.invoiced(appointment));ClinicalTreatmentRules.performed(input.performed,store.attended(appointment),clock.instant());var units=BusinessValues.units(input.units);var day=input.performed.atZone(BusinessTime.ZONE).toLocalDate();schedules.eligible(dentist,facts.clinic(),day);booking.treatments(dentist,day,List.of(input.treatment),true);var price=store.price(input.treatment);var subtotal=BusinessValues.subtotal(units.toPlainString(),price.toPlainString());long id=store.record(appointment,input.treatment,dentist,units,price,subtotal,input.performed);return result(appointment,id,null,null,null);});return resolve(command,result,true);
    }
    public Map<String,Object> complete(AtomicCommandExecutor.Command command,long appointment)throws Exception{
        var result=commands.execute(command,actor->doctor(actor,appointment,"completeAppointment"),actor->{long dentist=doctor(actor,appointment,"completeAppointment");store.lock(appointment,dentist);var facts=appointments.facts(appointment);ClinicalTreatmentRules.open(facts.status(),store.invoiced(appointment));schedules.eligible(dentist,facts.clinic(),clock.instant().atZone(BusinessTime.ZONE).toLocalDate());if(store.rows(appointment).isEmpty())throw new DomainFailure(422,"ACTUAL_TREATMENT_REQUIRED");store.complete(appointment,clock.instant(),actor.subjectId(),command.key());return result(appointment,null,null,null,null);});return resolve(command,result,false);
    }
    public View notes(AtomicCommandExecutor.Command command,long appointment,String text,String etag)throws Exception{
        var result=commands.execute(command,actor->doctor(actor,appointment,"updateClinicalNotes"),actor->{long dentist=doctor(actor,appointment,"updateClinicalNotes");store.lock(appointment,dentist);var facts=appointments.facts(appointment);ClinicalTreatmentRules.open(facts.status(),store.invoiced(appointment));if(text==null || text.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>65535)throw new DomainFailure(422,"CLINICAL_NOTES_INVALID");CanonicalJson.requireMatch(etag,noteVersion(appointment));String old=store.notes(appointment);store.notes(appointment,text,clock.instant());var changes=new LinkedHashMap<String,Object>();changes.put("old",old);changes.put("new",text);return result(appointment,null,null,null,changes);});return new View(resolve(command,result,false),CanonicalJson.etag(noteVersion(appointment)));
    }
    public Map<String,Object> context(String token,String client,long appointment,String request){var failedActor=new IdentityGate.Identity[1];AuditWriter.onRollback(audit,()->failedActor[0],"getClinicalContext",request);var actor=gate.authenticate(token,client);failedActor[0]=actor;long dentist=doctor(actor,appointment,"getClinicalContext");store.lock(appointment,dentist);var facts=appointments.facts(appointment);if(!Set.of("IN_PROGRESS","COMPLETED","INVOICED").contains(facts.status()))throw new DomainFailure(409,"CLINICAL_CONTEXT_NOT_AVAILABLE");schedules.eligible(dentist,facts.clinic(),clock.instant().atZone(BusinessTime.ZONE).toLocalDate());patients.lock(facts.patient());var body=new LinkedHashMap<String,Object>();body.put("appointment",booking.view(appointment));body.put("patient_allergy_review_status",patients.raw(facts.patient()).get("allergy_review_status"));body.put("self_reported_allergies",patients.view(facts.patient()).get("self_reported_allergies"));body.put("allergy_records",patients.allergyRows(facts.patient()).stream().map(patients::allergyView).toList());body.put("problems_or_special_needs",store.notes(appointment));body.put("applied_treatments",store.rows(appointment));audit.success(actor,"getClinicalContext","Appointment",Long.toString(appointment),List.of(facts.clinic()),request);return body;}
    public Map<String,Object> applied(String token,String client,long id,String request){var failedActor=new IdentityGate.Identity[1];AuditWriter.onRollback(audit,()->failedActor[0],"getAppliedTreatment",request);var actor=gate.authenticate(token,client);failedActor[0]=actor;var row=store.raw(id);long appointment=Long.parseLong((String)row.get("appointment_id"));boolean own=actor.dentistId()!=null && Long.toString(actor.dentistId()).equals(row.get("dentist_id"));if(own)doctor(actor,appointment,"getAppliedTreatment");else priceAuthority(actor,id);store.lock(appointment,own?actor.dentistId():null);if(own)doctor(actor,appointment,"getAppliedTreatment");else priceAuthority(actor,id);var view=store.view(id);audit.successChanges(actor,"getAppliedTreatment","AppliedTreatment",Long.toString(id),List.of(appointments.facts(appointment).clinic()),request,null,null,JSON.writeValueAsString(Map.of("price_snapshot_etag",view.get("etag"))));return view;}
    public Map<String,Object> correct(AtomicCommandExecutor.Command command,long id,String price,String reason,String verification,String etag)throws Exception{
        var result=commands.execute(command,actor->priceAuthority(actor,id),actor->{var before=store.raw(id);long appointment=Long.parseLong((String)before.get("appointment_id"));store.lock(appointment,null);priceAuthority(actor,id);var facts=appointments.facts(appointment);if(!Set.of("IN_PROGRESS","COMPLETED").contains(facts.status()) || store.invoiced(appointment))throw new DomainFailure(409,"CLINICAL_RECORD_READ_ONLY");before=store.raw(id);String current=CanonicalJson.etag(JSON.writeValueAsString(before));CanonicalJson.requireMatch(etag,JSON.writeValueAsString(before));if(!Objects.equals(current,verification) || !store.priceEvidence(actor.subjectId(),id,facts.clinic(),verification))throw new DomainFailure(403,"PRICE_VERIFICATION_REQUIRED");PatientRules.text(reason,255,false);var updated=BusinessValues.unitPrice(price);var subtotal=BusinessValues.subtotal((String)before.get("standard_units"),updated.toPlainString());store.correct(id,updated,subtotal);return result(appointment,id,reason,verification,Map.of("old",before,"new",store.raw(id)));});return resolve(command,result,true);
    }
    @Override @Transactional(propagation=Propagation.NOT_SUPPORTED)public Set<String> operations(){return Set.of("recordAppliedTreatment","completeAppointment","updateClinicalNotes","correctTreatmentPrice");}
    @Override public void authorize(IdentityGate.Identity actor,String operation,String refs){if(!operations().contains(operation))throw new DomainFailure(403,"ACCESS_DENIED");if(operation.equals("correctTreatmentPrice"))gate.staffClinics(actor,"HEADQUARTERS",operation);else gate.staffClinics(actor,"DENTIST",operation);if(refs!=null)for(var node:JSON.readTree(refs)){String ref=node.asText();if(ref.startsWith("Appointment:")){long id=Long.parseLong(ref.substring(12));if(operation.equals("correctTreatmentPrice"))gate.requireStaff(actor,"HEADQUARTERS",operation,appointments.facts(id).clinic());else doctor(actor,id,operation);}else if(ref.startsWith("AppliedTreatment:")){long id=Long.parseLong(ref.substring(17));if(operation.equals("correctTreatmentPrice"))priceAuthority(actor,id);else if(!Long.toString(Objects.requireNonNull(actor.dentistId())).equals(store.raw(id).get("dentist_id")))throw new DomainFailure(403,"ACCESS_DENIED");}else throw new DomainFailure(403,"ACCESS_DENIED");}}
}

